import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ setShowLoginModal, handleLoginSubmit }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    return (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
            <div style={{ background: 'white', width: '700px', height: '400px', display: 'flex', borderRadius: '20px', overflow: 'hidden' }}>
                {/* වම් පැත්ත */}
                <div style={{ width: '40%', background: '#1b5e20', color: 'white', padding: '40px', display: 'flex', alignItems: 'center' }}>
                    <h1>Aura Pan Saku<br/>Educational<br/>Institute</h1>
                </div>
                {/* දකුණු පැත්ත */}
                <div style={{ width: '60%', padding: '50px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                    <h2>Welcome Back!</h2>
                    <form onSubmit={(e) => { e.preventDefault(); handleLoginSubmit(username, password); }}>
                        <label>User Name</label>
                        <input type="text" onChange={(e) => setUsername(e.target.value)} style={{ width: '100%', padding: '10px', margin: '10px 0', border: '1px solid #ddd', borderRadius: '5px' }} required />
                        <label>Password</label>
                        <input type="password" onChange={(e) => setPassword(e.target.value)} style={{ width: '100%', padding: '10px', margin: '10px 0', border: '1px solid #ddd', borderRadius: '5px' }} required />
                        <button type="submit" style={{ width: '100%', padding: '12px', background: '#2e7d32', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', marginTop: '20px' }}>Login</button>
                        <button type="button" onClick={() => setShowLoginModal(false)} style={{ width: '100%', padding: '10px', marginTop: '10px', background: 'none', border: 'none', cursor: 'pointer' }}>Cancel</button>
                    </form>
                </div>
            </div>
        </div>
    );
};
export default Login;
